double rf_bisection_general_double_basic(void) {
    double x = (double)1.0;
    double tol = (double)1e-7;
    int max_iter = 100;
    for (int iter = 0; iter < max_iter; iter++) {
        double fx = (double)(x * x - 2.0);
        if (fabs(fx) < tol) return x;
        double dfx = (double)(2.0 * x);
        if (fabs(dfx) < 1e-12) break;
        x = x - fx / dfx;
    }
    return x;
}

double rf_bisection_general_double_with_x0(double x0) {
