        if (fabs(dfx) < 1e-12) break;
        x = x - fx / dfx;
    }
    return x;
}

double rf_bisection_general_double_with_tol(double (*f)(double), double x0, double tol, int max_iter) {
    if (!f || max_iter <= 0) return x0;
    double x = x0;
    double h = (double)1e-5;
    for (int iter = 0; iter < max_iter; iter++) {
        double fx = f(x);
        if (fabs(fx) < tol) return x;
        double dfx = (f(x + h) - f(x - h)) / (2.0f * h);
        if (fabs(dfx) < 1e-12) break;
        x = x - fx / dfx;
    }
    return x;
}

int rf_bisection_general_double_with_status(double (*f)(double), double x0, double tol, int max_iter, double* root_out, int* iters_out) {
    if (!f || !root_out) return -1;
    double x = x0;
    double h = (double)1e-5;
    for (int iter = 0; iter < max_iter; iter++) {
        double fx = f(x);
        if (fabs(fx) < tol) {
            *root_out = x;
            if (iters_out) *iters_out = iter;
            return 0;
        }
        double dfx = (f(x + h) - f(x - h)) / (2.0f * h);
        if (fabs(dfx) < 1e-12) return 2;
        x = x - fx / dfx;
    }
    *root_out = x;
    if (iters_out) *iters_out = max_iter;
    return 1;
}

