double rf_bisection_colebrook_double_basic(void) {
    double x = (double)0.02;
    double tol = (double)1e-7;
    int max_iter = 100;
    for (int iter = 0; iter < max_iter; iter++) {
        double fx = (double)(1.0 / sqrt(x) + 2.0 * log10(0.0001 / 3.7 + 2.51 / (100000.0 * sqrt(x))));
        if (fabs(fx) < tol) return x;
        double dfx = (double)(-0.5 * pow(x, -1.5));
        if (fabs(dfx) < 1e-12) break;
        x = x - fx / dfx;
    }
    return x;
}

