    double tol = (double)1e-7;
    int max_iter = 100;
    for (int iter = 0; iter < max_iter; iter++) {
        double fx = (double)((10.0 + 3.592 / (x * x)) * (x - 0.04267) - 0.08206 * 300.0);
        if (fabs(fx) < tol) return x;
        double dfx = (double)(10.0 - 3.592 / (x * x) + 7.184 * 0.04267 / (x * x * x));
        if (fabs(dfx) < 1e-12) break;
        x = x - fx / dfx;
    }
    return x;
}

