    double tol = (double)1e-7;
    int max_iter = 100;
    for (int iter = 0; iter < max_iter; iter++) {
        double fx = (double)(x / (1.0 - x) - 0.5 * 10.0);
        if (fabs(fx) < tol) return x;
        double dfx = (double)(1.0 / pow(1.0 - x, 2));
        if (fabs(dfx) < 1e-12) break;
        x = x - fx / dfx;
    }
    return x;
}

