bool ls_gauss_elimination_2x2_double_solve(const double A[2][2], const double b[2], double x[2]) {
    double aug[2][2 + 1];
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) aug[i][j] = A[i][j];
        aug[i][2] = b[i];
    }
    for (int i = 0; i < 2; i++) {
        int pivot = i;
        for (int k = i + 1; k < 2; k++) {
            if (fabs(aug[k][i]) > fabs(aug[pivot][i])) pivot = k;
        }
        for (int j = 0; j <= 2; j++) {
            double tmp = aug[i][j]; aug[i][j] = aug[pivot][j]; aug[pivot][j] = tmp;
        }
        if (fabs(aug[i][i]) < 1e-12) return false;
        for (int k = i + 1; k < 2; k++) {
            double factor = aug[k][i] / aug[i][i];
            for (int j = i; j <= 2; j++) aug[k][j] -= factor * aug[i][j];
        }
    }
    for (int i = 2 - 1; i >= 0; i--) {
        double sum = aug[i][2];
        for (int j = i + 1; j < 2; j++) sum -= aug[i][j] * x[j];
        x[i] = sum / aug[i][i];
    }
    return true;
}

double ls_gauss_elimination_2x2_double_residual(const double A[2][2], const double b[2], const double x[2]) {
    double norm = 0;
    for (int i = 0; i < 2; i++) {
        double ax_i = 0;
        for (int j = 0; j < 2; j++) ax_i += A[i][j] * x[j];
        double diff = ax_i - b[i];
        norm += diff * diff;
    }
    return (double)sqrt(norm);
}

double ls_gauss_elimination_2x2_double_determinant(const double A[2][2]) {
    double M[2][2];
    for (int i = 0; i < 2; i++) for (int j = 0; j < 2; j++) M[i][j] = A[i][j];
    double det = 1;
    for (int i = 0; i < 2; i++) {
        int pivot = i;
        for (int k = i + 1; k < 2; k++) if (fabs(M[k][i]) > fabs(M[pivot][i])) pivot = k;
        if (pivot != i) {
            for (int j = 0; j < 2; j++) { double t = M[i][j]; M[i][j] = M[pivot][j]; M[pivot][j] = t; }
            det = -det;
        }
        if (fabs(M[i][i]) < 1e-12) return 0;
        det *= M[i][i];
        for (int k = i + 1; k < 2; k++) {
            double f = M[k][i] / M[i][i];
            for (int j = i; j < 2; j++) M[k][j] -= f * M[i][j];
        }
    }
    return det;
}

bool ls_gauss_elimination_2x2_double_is_diagonally_dominant(const double A[2][2]) {
    for (int i = 0; i < 2; i++) {
        double sum = 0;
        for (int j = 0; j < 2; j++) if (i != j) sum += fabs(A[i][j]);
        if (fabs(A[i][i]) <= sum) return false;
    }
    return true;
}

bool ls_gauss_elimination_2x2_double_inverse(const double A[2][2], double inv[2][2]) {
    for (int i = 0; i < 2; i++) {
        double e[2] = {0};
        e[i] = 1;
        double col[2];
        if (!ls_gauss_elimination_2x2_double_solve(A, e, col)) return false;
        for (int r = 0; r < 2; r++) inv[r][i] = col[r];
    }
    return true;
}

double ls_gauss_elimination_2x2_double_condition_number(const double A[2][2]) {
    double inv[2][2];
    if (!ls_gauss_elimination_2x2_double_inverse(A, inv)) return (double)-1;
    double norm_A = 0, norm_inv = 0;
    for (int j = 0; j < 2; j++) {
        double sA = 0, sInv = 0;
        for (int i = 0; i < 2; i++) { sA += fabs(A[i][j]); sInv += fabs(inv[i][j]); }
        if (sA > norm_A) norm_A = sA;
        if (sInv > norm_inv) norm_inv = sInv;
    }
    return norm_A * norm_inv;
}

