double interp_lagrange_3pts_double_eval(const double x_pts[3], const double y_pts[3], double x) {
    double result = 0;
    for (int i = 0; i < 3; i++) {
        double term = y_pts[i];
        for (int j = 0; j < 3; j++) {
            if (i != j) {
                term *= (x - x_pts[j]) / (x_pts[i] - x_pts[j]);
            }
        }
        result += term;
    }
    return result;
}

void interp_lagrange_3pts_double_eval_batch(const double x_pts[3], const double y_pts[3], const double* queries, size_t m, double* out_results) {
    if (!queries || !out_results) return;
    for (size_t k = 0; k < m; k++) {
        out_results[k] = interp_lagrange_3pts_double_eval(x_pts, y_pts, queries[k]);
    }
}

double interp_lagrange_3pts_double_derivative(const double x_pts[3], const double y_pts[3], double x) {
    double h = (double)1e-5;
    return (interp_lagrange_3pts_double_eval(x_pts, y_pts, x + h) - interp_lagrange_3pts_double_eval(x_pts, y_pts, x - h)) / (2.0f * h);
}

double interp_lagrange_3pts_double_error_bound(const double x_pts[3], double x, double max_derivative) {
    double prod = 1;
    for (int i = 0; i < 3; i++) prod *= fabs(x - x_pts[i]);
    double fact = 1;
    for (int i = 2; i <= 3; i++) fact *= i;
    return prod * max_derivative / fact;
}

void interp_lagrange_3pts_double_coefficients(const double x_pts[3], const double y_pts[3], double coeffs[3]) {
    for (int i = 0; i < 3; i++) coeffs[i] = y_pts[i];
    for (int j = 1; j < 3; j++) {
        for (int i = 3 - 1; i >= j; i--) {
            coeffs[i] = (coeffs[i] - coeffs[i - 1]) / (x_pts[i] - x_pts[i - j]);
        }
    }
}

