double diff_finite_difference_1e_1_double_eval(double (*f)(double), double x) {
    if (!f) return 0;
    double h = (double)1e-1;
    return (f(x + h) - f(x - h)) / (2.0f * h);
}

double diff_finite_difference_1e_1_double_eval_second(double (*f)(double), double x) {
    if (!f) return 0;
    double h = (double)1e-1;
    return (f(x + h) - 2.0f * f(x) + f(x - h)) / (h * h);
}

double diff_finite_difference_1e_1_double_eval_third(double (*f)(double), double x) {
    if (!f) return 0;
    double h = (double)1e-1;
    return (f(x + 2.0f * h) - 2.0f * f(x + h) + 2.0f * f(x - h) - f(x - 2.0f * h)) / (2.0f * h * h * h);
}

double diff_finite_difference_1e_1_double_richardson_extrapolation(double (*f)(double), double x) {
    if (!f) return 0;
    double h = (double)1e-1;
    double d1 = (f(x + h) - f(x - h)) / (2.0f * h);
    double d2 = (f(x + 0.5f * h) - f(x - 0.5f * h)) / h;
    return (4.0f * d2 - d1) / 3.0f;
}

