double integ_trapezoidal_10n_double_eval(double (*f)(double), double a, double b) {
    if (!f || a == b) return 0;
    double h = (b - a) / 10;
    double sum = 0.5f * (f(a) + f(b));
    for (int i = 1; i < 10; i++) {
        sum += f(a + i * h);
    }
    return sum * h;
}

double integ_trapezoidal_10n_double_eval_tabulated(const double* y_data, double h) {
    if (!y_data || h <= 0) return 0;
    double sum = 0.5f * (y_data[0] + y_data[10]);
    for (int i = 1; i < 10; i++) {
        sum += y_data[i];
    }
    return sum * h;
}

void integ_trapezoidal_10n_double_cumulative(double (*f)(double), double a, double b, double out_cum[10 + 1]) {
    if (!f || !out_cum) return;
    double h = (b - a) / 10;
    out_cum[0] = 0;
    for (int i = 1; i <= 10; i++) {
        double x_prev = a + (i - 1) * h;
        double x_curr = a + i * h;
        out_cum[i] = out_cum[i - 1] + 0.5f * (f(x_prev) + f(x_curr)) * h;
    }
}

double integ_trapezoidal_10n_double_adaptive_step(double (*f)(double), double a, double b, double* error_est) {
    double fine = integ_trapezoidal_10n_double_eval(f, a, b);
    double h_coarse = (b - a) / (5);
    double coarse = 0.5f * (f(a) + f(b));
    for (int i = 1; i < (5); i++) coarse += f(a + i * h_coarse);
    coarse *= h_coarse;
    if (error_est) *error_est = (double)fabs(fine - coarse) / 3.0f;
    return fine;
}

