double ode_euler_10steps_double_solve(double (*f)(double, double), double t0, double y0, double t_end) {
    if (!f) return y0;
    double h = (t_end - t0) / 10;
    double t = t0;
    double y = y0;
    for (int i = 0; i < 10; i++) {
        double k1 = f(t, y);
        double k2 = f(t + 0.5f * h, y + 0.5f * h * k1);
        double k3 = f(t + 0.5f * h, y + 0.5f * h * k2);
        double k4 = f(t + h, y + h * k3);
        y += (h / 6.0f) * (k1 + 2.0f * k2 + 2.0f * k3 + k4);
        t += h;
    }
    return y;
}

void ode_euler_10steps_double_trajectory(double (*f)(double, double), double t0, double y0, double t_end, double t_out[10 + 1], double y_out[10 + 1]) {
    if (!f || !t_out || !y_out) return;
    double h = (t_end - t0) / 10;
    double t = t0;
    double y = y0;
    t_out[0] = t;
    y_out[0] = y;
    for (int i = 0; i < 10; i++) {
        double k1 = f(t, y);
        double k2 = f(t + 0.5f * h, y + 0.5f * h * k1);
        double k3 = f(t + 0.5f * h, y + 0.5f * h * k2);
        double k4 = f(t + h, y + h * k3);
        y += (h / 6.0f) * (k1 + 2.0f * k2 + 2.0f * k3 + k4);
        t += h;
        t_out[i + 1] = t;
        y_out[i + 1] = y;
    }
}

double ode_euler_10steps_double_error_estimate(double (*f)(double, double), double t0, double y0, double t_end) {
    double y_full = ode_euler_10steps_double_solve(f, t0, y0, t_end);
    double t_mid = t0 + 0.5f * (t_end - t0);
    double y_half1 = ode_euler_10steps_double_solve(f, t0, y0, t_mid);
    double y_half2 = ode_euler_10steps_double_solve(f, t_mid, y_half1, t_end);
    return (double)fabs(y_half2 - y_full) / 15.0f;
}

void ode_euler_10steps_double_second_order(double (*f)(double, double, double), double t0, double y0, double v0, double t_end, double* y_final, double* v_final) {
    if (!f) return;
    double h = (t_end - t0) / 10;
    double t = t0, y = y0, v = v0;
    for (int i = 0; i < 10; i++) {
        double a = f(t, y, v);
        y += v * h + 0.5f * a * h * h;
        double a_next = f(t + h, y, v + a * h);
        v += 0.5f * (a + a_next) * h;
        t += h;
    }
    if (y_final) *y_final = y;
    if (v_final) *v_final = v;
}

