bool fit_linear_regression_5pts_double_fit(const double x[5], const double y[5], double* slope, double* intercept) {
    if (!x || !y || !slope || !intercept) return false;
    double sum_x = 0, sum_y = 0, sum_xy = 0, sum_xx = 0;
    for (int i = 0; i < 5; i++) {
        sum_x += x[i];
        sum_y += y[i];
        sum_xy += x[i] * y[i];
        sum_xx += x[i] * x[i];
    }
    double denom = 5 * sum_xx - sum_x * sum_x;
    if (fabs(denom) < 1e-12) return false;
    *slope = (5 * sum_xy - sum_x * sum_y) / denom;
    *intercept = (sum_y - (*slope) * sum_x) / 5;
    return true;
}

double fit_linear_regression_5pts_double_predict(double x, double slope, double intercept) {
    return slope * x + intercept;
}

double fit_linear_regression_5pts_double_r_squared(const double x[5], const double y[5], double slope, double intercept) {
    double mean_y = 0;
    for (int i = 0; i < 5; i++) mean_y += y[i];
    mean_y /= 5;
    double ss_tot = 0, ss_res = 0;
    for (int i = 0; i < 5; i++) {
        double y_pred = slope * x[i] + intercept;
        ss_res += (y[i] - y_pred) * (y[i] - y_pred);
        ss_tot += (y[i] - mean_y) * (y[i] - mean_y);
    }
    if (ss_tot < 1e-12) return 1;
    return 1 - ss_res / ss_tot;
}

double fit_linear_regression_5pts_double_rmse(const double x[5], const double y[5], double slope, double intercept) {
    double sum_sq = 0;
    for (int i = 0; i < 5; i++) {
        double diff = y[i] - (slope * x[i] + intercept);
        sum_sq += diff * diff;
    }
    return (double)sqrt(sum_sq / 5);
}

